css:
.money-receipt-print {
    width: 100%;
    font-family: "Times New Roman", Times, serif;
    color: #000;
    font-size: 12px;
    line-height: 1.45;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

@page {
    size: A4;
    margin: 8mm 10mm 8mm 10mm;
}

.letter-head {
    width: 100%;
    margin-bottom: 40px !important;
}

.receipt-body {
    width: 82%;
    margin: 0 auto;
    padding: 0;
    box-sizing: border-box;
}

.receipt-date {
    font-size: 12px;
    text-align: left;
    margin: 18px 0 22px 0;
}

.customer-block {
    text-align: left;
    font-size: 12px;
    line-height: 1.45;
    margin-bottom: 34px;
}

.customer-name {
    font-weight: 700;
}

.receipt-subject {
    font-size: 12px;
    font-weight: 700;
    text-decoration: underline;
    margin: 0 0 28px 0;
    text-align: left;
}

.receipt-salutation {
    font-size: 12px;
    margin-bottom: 22px;
    text-align: left;
}

.receipt-paragraph {
    font-size: 12px;
    line-height: 1.55;
    margin-bottom: 28px;
    text-align: justify;
    max-width: 860px;
    -webkit-font-smoothing: antialiased;
    word-wrap: break-word !important;
}

.receipt-note {
    font-size: 12px;
    margin-bottom: 42px;
    text-align: left;
}

.date-line {
    font-size: 12px;
    margin-bottom: 15px;
    margin-top: 0 !important;
    line-height: 1.3;
    margin-top: -10px !important;
    margin-bottom: 10px !important;
}

.thankyou-text {
    font-size: 12px;
    margin-bottom: 46px;
    text-align: left;
}

.sincerely-text {
    font-size: 12px;
    text-align: left;
    margin-bottom: 70px;
    padding-right: 18px;
}

.signature-row {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 48px;
}

.signature-box {
    width: 42%;
}

.signature-line {
    border-top: 1px solid #000;
    width: 100%;
    margin-bottom: 8px;
}

.signature-label {
    font-size: 11px;
    color: #333;
    text-align: left;
}

.receipt-footer-note {
    border-top: 1px dotted #bbb;
    padding-top: 12px;
    margin-top: 12px;
    text-align: center;
    font-size: 11px;
    color: #666;
    margin-bottom: 180px;
}

.letter-head-footer {
    width: 82%;
    margin: 0 auto;
}

table, tr, td, th {
    page-break-inside: avoid;
}
